// swift-tools-version: 5.9
import PackageDescription

// Swift Package for command-line builds and unit tests.
// The shipping app is built from FamilyRoom.xcodeproj (generated by XcodeGen from project.yml),
// which adds the iCloud/CloudKit entitlements the package build cannot carry.
let package = Package(
    name: "FamilyRoom",
    platforms: [.macOS(.v14), .iOS(.v17)],
    products: [
        .executable(name: "FamilyRoom", targets: ["FamilyRoom"])
    ],
    targets: [
        .executableTarget(
            name: "FamilyRoom",
            path: "Sources/FamilyRoom",
            resources: [.process("Resources")]
        ),
        .testTarget(
            name: "FamilyRoomTests",
            dependencies: ["FamilyRoom"],
            path: "Tests/UnitTests"
        )
    ]
)
